class Solution {
    public boolean canAttendMeetings(int[][] intervals) {
        java.util.Arrays.sort(intervals, (a, b) -> {
            int byStart = Integer.compare(a[0], b[0]);
            return byStart != 0 ? byStart : Integer.compare(a[1], b[1]);
        });
        for (int i = 1; i < intervals.length; i++) {
            if (intervals[i][0] < intervals[i - 1][1]) {
                return false;
            }
        }
        return true;
    }
}

class Solution {
    public boolean canAttendMeetings(int[][] intervals) {
        for (int i = 0; i < intervals.length; i++) {
            for (int j = i + 1; j < intervals.length; j++) {
                if (intervals[i][0] < intervals[j][1] && intervals[j][0] < intervals[i][1]) {
                    return false;
                }
            }
        }
        return true;
    }
}

class Solution {
    public boolean canAttendMeetings(int[][] intervals) {
        int n = intervals.length;
        int[] starts = new int[n];
        int[] ends = new int[n];
        for (int i = 0; i < n; i++) {
            starts[i] = intervals[i][0];
            ends[i] = intervals[i][1];
        }
        java.util.Arrays.sort(starts);
        java.util.Arrays.sort(ends);
        for (int i = 1; i < n; i++) {
            if (starts[i] < ends[i - 1]) {
                return false;
            }
        }
        return true;
    }
}

import java.util.*;

class Solution {
    public boolean canAttendMeetings(int[][] intervals) {
        TreeMap<Integer, Integer> events = new TreeMap<>();
        for (int[] interval : intervals) {
            events.merge(interval[0], 1, Integer::sum);
            events.merge(interval[1], -1, Integer::sum);
        }
        int active = 0;
        for (int delta : events.values()) {
            active += delta;
            if (active > 1) {
                return false;
            }
        }
        return true;
    }
}

import java.util.*;

class Solution {
    public boolean canAttendMeetings(int[][] intervals) {
        TreeMap<Integer, Integer> calendar = new TreeMap<>();
        for (int[] interval : intervals) {
            int start = interval[0];
            int end = interval[1];
            Map.Entry<Integer, Integer> previous = calendar.floorEntry(start);
            if (previous != null && previous.getValue() > start) {
                return false;
            }
            Map.Entry<Integer, Integer> next = calendar.ceilingEntry(start);
            if (next != null && end > next.getKey()) {
                return false;
            }
            calendar.put(start, Math.max(calendar.getOrDefault(start, end), end));
        }
        return true;
    }
}
